import re
from datetime import datetime

_UPDATED_FORMATS = ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y")
_EXT_MARKER = re.compile(r"ext|x|#", re.IGNORECASE)


def _get(row, key):
    value = row.get(key)
    return "" if value is None else str(value)


def _normalize_email(raw):
    """Return the normalized email, or "" if it is not valid."""
    s = raw.strip()
    m = re.search(r"<([^<>]*)>", s)
    if m:
        s = m.group(1)
    s = s.strip().lower()

    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.replace(".", "").split("+", 1)[0]
            s = local + "@gmail.com"

    if s.count("@") != 1:
        return ""
    local, domain = s.split("@")
    if local and "." in domain and not domain.startswith(".") and not domain.endswith("."):
        return s
    return ""


def _normalize_phone(raw):
    """Return the normalized 10-digit phone, or "" if it is not valid."""
    m = _EXT_MARKER.search(raw)
    digits = re.sub(r"[^0-9]", "", raw[:m.start()] if m else raw)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    if len(digits) == 10 and digits[0] not in "01":
        return digits
    return ""


def _normalize_zip(raw):
    s = raw.strip()
    if re.fullmatch(r"[0-9]{4,5}-[0-9]{4}", s):
        s = s.split("-")[0]
    if re.fullmatch(r"[0-9]{4}", s):
        s = "0" + s
    return s if re.fullmatch(r"[0-9]{5}", s) else ""


def _normalize_name(raw):
    s = raw.strip()
    if s and (s.isupper() or s.islower()):
        s = s.title()
    return s


def _parse_updated(raw):
    text = raw.strip()
    for fmt in _UPDATED_FORMATS:
        try:
            return datetime.strptime(text, fmt)
        except ValueError:
            continue
    raise ValueError(f"Unrecognized 'updated' value: {raw!r}")


def _pick(members, field):
    """Choose the value for `field` from the group: manual first, then most
    recent `updated`, then earliest input row. Returns "" if no row has it."""
    candidates = [m for m in members if m[field]]
    if not candidates:
        return ""
    # Stable sorts applied from lowest to highest priority.
    ordered = sorted(candidates, key=lambda m: m["index"])
    ordered = sorted(ordered, key=lambda m: m["updated"], reverse=True)
    ordered = sorted(ordered, key=lambda m: not m["is_manual"])
    return ordered[0][field]


def dedupe_contacts(rows):
    # Normalize each row and drop rows with no valid email or phone.
    records = []
    for index, row in enumerate(rows):
        email = _normalize_email(_get(row, "email"))
        phone = _normalize_phone(_get(row, "phone"))
        if not email and not phone:
            continue

        source = _get(row, "source").strip().lower()
        tags = {
            t.strip().lower()
            for t in re.split(r"[;,]", _get(row, "tags"))
            if t.strip()
        }
        opted_out = _get(row, "opted_out").strip().lower() in ("y", "yes", "true", "1")

        records.append({
            "index": index,
            "first_name": _normalize_name(_get(row, "first_name")),
            "last_name": _normalize_name(_get(row, "last_name")),
            "zip": _normalize_zip(_get(row, "zip")),
            "email": email,
            "phone": phone,
            "source": source,
            "is_manual": source == "manual",
            "tags": tags,
            "opted_out": opted_out,
            "updated": _parse_updated(_get(row, "updated")),
        })

    # Group matching rows with union-find (handles transitive matches).
    parent = list(range(len(records)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    first_by_email = {}
    first_by_phone_last = {}
    for i, rec in enumerate(records):
        if rec["email"]:
            if rec["email"] in first_by_email:
                union(first_by_email[rec["email"]], i)
            else:
                first_by_email[rec["email"]] = i
        if rec["phone"] and rec["last_name"]:
            key = (rec["phone"], rec["last_name"].casefold())
            if key in first_by_phone_last:
                union(first_by_phone_last[key], i)
            else:
                first_by_phone_last[key] = i

    groups = {}
    for i in range(len(records)):
        groups.setdefault(find(i), []).append(i)

    # Each group's index list is already in input order, so g[0] is its
    # earliest row. Sort groups by that to keep first-appearance order.
    ordered_groups = sorted(groups.values(), key=lambda g: g[0])

    result = []
    for group in ordered_groups:
        members = [records[i] for i in group]
        all_tags = set().union(*(m["tags"] for m in members))
        result.append({
            "first_name": _pick(members, "first_name"),
            "last_name": _pick(members, "last_name"),
            "zip": _pick(members, "zip"),
            "email": _pick(members, "email"),
            "phone": _pick(members, "phone"),
            "source": _pick(members, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": "Y" if any(m["opted_out"] for m in members) else "N",
            "updated": max(m["updated"] for m in members).strftime("%Y-%m-%d"),
        })

    return result
